// Package htmlentity decodes the character references that CommonMark 0.31.2
// recognizes, with the names of the entities package 3.0.1, which commonmark.js
// 0.31.2 reads them from. A numeric reference in text is its code point, as
// CommonMark states (§2.5) and as GitHub and VS Code render it (the slug vectors of
// store/testdata/slug), and in an attribute value as the HTML standard reads it. The
// named references are generated by go generate (gen/main.go)
// from testdata/entities-3.0.1.json, and a test requires table.go to be that
// generation. The data file is the entities package's own, distributed under its
// BSD-2-Clause license, whose text stands beside it in
// testdata/entities-3.0.1.LICENSE.
package htmlentity

//go:generate go run ./gen

import (
	"encoding/json"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"
)

// Source is the public URL of the data file that the table is generated from.
const Source = "https://unpkg.com/entities@3.0.1/lib/maps/entities.json"

// replaced maps the numeric references whose code point the HTML standard replaces
// in an attribute value, besides those that every reading replaces by U+FFFD: the C1
// controls that stand for windows-1252 characters. CommonMark replaces none of them
// in text.
var replaced = map[int64]rune{
	0x80: 0x20AC, 0x82: 0x201A, 0x83: 0x0192, 0x84: 0x201E, 0x85: 0x2026,
	0x86: 0x2020, 0x87: 0x2021, 0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160, 0x8B: 0x2039,
	0x8C: 0x0152, 0x8E: 0x017D, 0x91: 0x2018, 0x92: 0x2019, 0x93: 0x201C, 0x94: 0x201D,
	0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014, 0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161,
	0x9B: 0x203A, 0x9C: 0x0153, 0x9E: 0x017E, 0x9F: 0x0178,
}

// Reference returns the text of the character reference at the start of s and its
// length in bytes, or the length 0 when s starts with none. A reference is an
// ampersand, then either '#' and a decimal number of one to seven digits, or '#x'
// or '#X' and a hexadecimal number of one to six, or a name of two to thirty-two
// letters and digits that begins with a letter and is an entry of the table; a
// semicolon ends each. A name without its semicolon, or one that is not an entry,
// is no reference. A numeric reference renders its code point, U+FFFD for zero, a
// surrogate or a number above U+10FFFF (CommonMark 0.31.2, §2.5).
func Reference(s string) (string, int) {
	return reference(s, false)
}

// reference reads the character reference at the start of s; html replaces the
// numeric references of the windows-1252 C1 controls as the HTML standard does.
func reference(s string, html bool) (string, int) {
	if len(s) < 3 || s[0] != '&' {
		return "", 0
	}
	if s[1] == '#' {
		return numeric(s, html)
	}
	return name(s)
}

// numeric reads a numeric character reference at the start of s.
func numeric(s string, html bool) (string, int) {
	p, base, max := 2, 10, 7
	if p < len(s) && (s[p] == 'x' || s[p] == 'X') {
		p, base, max = p+1, 16, 6
	}
	start := p
	for p < len(s) && digitIn(s[p], base) {
		p++
	}
	if n := p - start; n < 1 || n > max || p >= len(s) || s[p] != ';' {
		return "", 0
	}
	v, err := strconv.ParseInt(s[start:p], base, 64)
	if err != nil {
		return "", 0
	}
	if r, ok := replaced[v]; ok && html {
		return string(r), p + 1
	}
	if v == 0 || v > 0x10FFFF || (0xD800 <= v && v <= 0xDFFF) {
		return "�", p + 1
	}
	return string(rune(v)), p + 1
}

// name reads a named character reference at the start of s.
func name(s string) (string, int) {
	if !letter(s[1]) {
		return "", 0
	}
	p := 2
	for p < len(s) && (letter(s[p]) || ('0' <= s[p] && s[p] <= '9')) {
		p++
	}
	if p-1 > 32 || p-1 < 2 || p >= len(s) || s[p] != ';' {
		return "", 0
	}
	text, ok := named[s[1:p]]
	if !ok {
		return "", 0
	}
	return text, p + 1
}

// Expand returns s with each character reference of it replaced by its text, as an
// attribute value of HTML reads it: as Reference reads it, except that the numeric
// reference of a C1 control that stands for a windows-1252 character is that
// character. A reference that Reference does not read stays.
func Expand(s string) string {
	if !strings.Contains(s, "&") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); {
		if s[i] == '&' {
			if text, n := reference(s[i:], true); n > 0 {
				b.WriteString(text)
				i += n
				continue
			}
		}
		b.WriteByte(s[i])
		i++
	}
	return b.String()
}

// digitIn reports whether c is a digit of base 10 or 16.
func digitIn(c byte, base int) bool {
	if '0' <= c && c <= '9' {
		return true
	}
	return base == 16 && (('a' <= c && c <= 'f') || ('A' <= c && c <= 'F'))
}

// letter reports whether c is an ASCII letter.
func letter(c byte) bool { return ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') }

// Render returns table.go for the entity data of the JSON file data, whose keys are
// entity names without their semicolons.
func Render(data []byte) ([]byte, error) {
	var entities map[string]string
	if err := json.Unmarshal(data, &entities); err != nil {
		return nil, err
	}
	names := make([]string, 0, len(entities))
	for n := range entities {
		names = append(names, n)
	}
	sort.Strings(names)
	var b strings.Builder
	b.WriteString("// Code generated by go generate from testdata/entities-" + Version + ".json; DO NOT EDIT.\n\n")
	b.WriteString("package htmlentity\n\n")
	b.WriteString("// named maps each entity name, without its semicolon, to its text.\n")
	b.WriteString("var named = map[string]string{\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t%s: %s,\n", strconv.Quote(n), strconv.Quote(entities[n]))
	}
	b.WriteString("}\n")
	return format.Source([]byte(b.String()))
}

// Version is the version of the entities package whose data the table holds.
const Version = "3.0.1"
